#!/usr/bin/env python3
"""Regenerate src/html_entities.h using Python's HTML5 character reference data."""

from html.entities import html5
from pathlib import Path


def main():
    lines = [
        "/* Generated by tools/generate_html_entities.py; do not edit manually.",
        " * Source: Python html.entities.html5, based on the HTML5 entity table:",
        " * https://html.spec.whatwg.org/entities.json",
        " * Only semicolon-terminated names are valid in CommonMark.",
        " */",
        "#ifndef VIEWMD_HTML_ENTITIES_H",
        "#define VIEWMD_HTML_ENTITIES_H",
        "",
        "typedef struct {",
        "  const gchar *name;",
        "  const gchar *utf8;",
        "} HtmlEntity;",
        "",
        "/* Sorted by name for binary search; values may contain two code points. */",
        "static const HtmlEntity html_entities[] = {",
    ]
    for name, value in sorted(html5.items()):
        if name.endswith(";"):
            utf8 = "".join(f"\\x{byte:02x}" for byte in value.encode("utf-8"))
            lines.append(f'  {{"&{name}", "{utf8}"}},')
    lines.extend(["};", "", "#endif /* VIEWMD_HTML_ENTITIES_H */", ""])
    target = Path(__file__).resolve().parents[1] / "src" / "html_entities.h"
    target.write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
